input.command:
cd /workspace/dataset && enc3(){ local -a a=(); local c; for ((c=$1;c<$2;c++)); do a+=( $((0xE0|c>>12)) $((0x80|(c>>6)&0x3F)) $((0x80|c&0x3F)) ); done; printf '.\\x%02x\\x%02x\\x%02x' "${a[@]}"; }
arg=$(printf "$(enc3 0x2F00 0x3000)")
line=$(./test8_executable --a '{}' --b "$arg" 2>&1 >/dev/null | sed -n '6p')
body=${line#*Type \'}; body=${body%\' is unknown to this type checker}
printf '%s\n' "$body" | awk -v base=$((0x2F00)) 'BEGIN{FS="."}{print "NF="NF; n=0; for(i=2;i<=NF;i++){e=(substr($i,1,1)=="\\")?1:0; if(e)n++; } print "escaped="n}'
printf '%s\n' "$body" | awk -v base=$((0x2F00)) 'BEGIN{FS="."}{for(i=2;i<=NF;i++){e=(substr($i,1,1)=="\\")?1:0; printf "%04X:%d ", base+i-2, e}}' | tr ' ' '\n' | grep ':1' | head -60

cd /workspace/dataset
enc2(){ local -a a=(); local c; for ((c=$1;c<$2;c++)); do a+=( $((0xC0|c>>6)) $((0x80|c&0x3F)) ); done; printf '.\\x%02x\\x%02x' "${a[@]}"; }
enc3(){ local -a a=(); local c; for ((c=$1;c<$2;c++)); do a+=( $((0xE0|c>>12)) $((0x80|(c>>6)&0x3F)) $((0x80|c&0x3F)) ); done; printf '.\\x%02x\\x%02x\\x%02x' "${a[@]}"; }
one(){ local lo=$1 hi=$2 f=$3; local arg line body
  arg=$(printf "$($f $lo $hi)")
  line=$(./test8_executable --a '{}' --b "$arg" 2>&1 >/dev/null | sed -n '6p')
  body=${line#*Type \'}; body=${body%\' is unknown to this type checker}
  printf '%s\n' "$body" | awk -v base=$lo -v n=$((hi-lo)) 'BEGIN{FS="."}{ if(NF-1!=n){printf "MISMATCH base=%d got=%d want=%d\n",base,NF-1,n > "/dev/stderr"} for(i=2;i<=NF;i++){printf "%d %d\n", base+i-2, (substr($i,1,1)=="\\")?1:0}}'
}
{
for ((b=0x80;b<0x800;b+=1024)); do one $b $((b+1024>0x800?0x800:b+1024)) enc2; done
for ((b=0x800;b<0xD800;b+=1024)); do one $b $((b+1024)) enc3; done
for ((b=0xE000;b<0x10000;b+=1024)); do one $b $((b+1024)) enc3; done
} > /tmp/bmp.txt 2>/tmp/bmp.err
echo "lines=$(wc -l < /tmp/bmp.txt)"; echo "errs:"; cat /tmp/bmp.err
awk '{ if($2!=p || $1!=pe+1){ if(p!=""){printf "%04X-%04X %s\n", s, pe, (p?"ESC":"raw")} s=$1; p=$2 } pe=$1 } END{printf "%04X-%04X %s\n", s, pe, (p?"ESC":"raw")}' /tmp/bmp.txt | grep ESC | head -200
